                gameState.players[1].isCurrentPlayer = true;
                gameState.players[0].isCurrentPlayer = false;

                // Actualizar display
                updatePlayerDisplay();
                document.getElementById('room-code-display').textContent = roomCode;

                // Mostrar lobby
                showScreen('lobby');

                // Ocultar botón de inicio (solo el host puede iniciar)
                document.getElementById('btn-start').classList.add('hidden');
                document.getElementById('lobby-status').innerHTML = `
                    <div>Esperando que el host inicie la partida...</div>
                `;
            });

            document.getElementById('btn-share').addEventListener('click', () => {
                const code = document.getElementById('room-code-display').textContent;
                const shareText = `¡Únete a mi partida de Trivia Master! Código: ${code}`;

                if (navigator.share) {
                    navigator.share({
                        title: 'Trivia Master',
                        text: shareText,
                        url: window.location.href
                    });
                } else {
                    // Fallback: copiar al portapapeles
                    navigator.clipboard.writeText(shareText).then(() => {
                        alert('¡Código copiado al portapapeles! Compártelo con tu amigo.');
                    });
                }
            });

            document.getElementById('btn-start').addEventListener('click', () => {
                // Iniciar juego
                gameState.gameStarted = true;
                showScreen('game');

                // Mostrar primera pregunta
                const question = getRandomQuestion();
                gameState.currentQuestion = question;
                showQuestion(question);
            });

            // Configurar botones de opciones
            document.querySelectorAll('.option-btn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    if (gameState.selectedAnswer !== null) return; // Ya se respondió

                    const selectedIndex = parseInt(e.target.dataset.index);
                    gameState.selectedAnswer = selectedIndex;

                    // Deshabilitar todos los botones
                    document.querySelectorAll('.option-btn').forEach(b => {
                        b.disabled = true;

                        // Marcar respuesta correcta
                        if (parseInt(b.dataset.index) === gameState.currentQuestion.c) {
                            b.classList.add('correct');
                        }

                        // Marcar respuesta incorrecta del jugador
                        if (parseInt(b.dataset.index) === selectedIndex && selectedIndex !== gameState.currentQuestion.c) {
                            b.classList.add('incorrect');
                        }
                    });

                    // Verificar respuesta
                    const isCorrect = selectedIndex === gameState.currentQuestion.c;

                    // Actualizar puntuación
                    if (isCorrect) {
                        const currentPlayerIndex = gameState.players.findIndex(p => p.isCurrentPlayer);
                        gameState.players[currentPlayerIndex].score += 10;
                        updatePlayerDisplay();
                    }

                    // Mostrar resultado después de un breve retraso
                    setTimeout(() => {
                        showResult(isCorrect, gameState.currentQuestion.e);
                        gameState.questionsAnswered++;
                    }, 1000);
                });
            });

            document.getElementById('btn-next').addEventListener('click', () => {
                // Reiniciar estado para siguiente pregunta
                gameState.selectedAnswer = null;

                // Cambiar turno
                gameState.players[0].isCurrentPlayer = !gameState.players[0].isCurrentPlayer;
                gameState.players[1].isCurrentPlayer = !gameState.players[1].isCurrentPlayer;
                updatePlayerDisplay();

                // Verificar si el juego ha terminado
                checkGameEnd();

                if (gameState.questionsAnswered < gameState.maxQuestions) {
                    // Mostrar siguiente pregunta
                    const question = getRandomQuestion();
                    gameState.currentQuestion = question;
                    showQuestion(question);
                }
            });

            document.getElementById('btn-play-again').addEventListener('click', () => {
                // Reiniciar estado del juego
                gameState.players[0].score = 0;
                gameState.players[1].score = 0;
                gameState.questionsAnswered = 0;
                gameState.selectedAnswer = null;
                gameState.gameStarted = false;

                // Volver a la pantalla de inicio
                showScreen('home');

                // Generar nuevo código de sala
                const newCode = generateRoomCode();
                gameState.roomCode = newCode;
                document.getElementById('room-code-display').textContent = newCode;

                // Restablecer nombres de jugadores
                gameState.players[0].name = gameState.isHost ? gameState.playerName : 'Jugador 1';
                gameState.players[1].name = gameState.isHost ? 'Esperando...' : gameState.playerName;
                gameState.players[0].isCurrentPlayer = gameState.isHost;
                gameState.players[1].isCurrentPlayer = !gameState.isHost;

                updatePlayerDisplay();
            });

            // Cargar nombre guardado si existe
            const savedName = localStorage.getItem('triviaMasterName');
            if (savedName) {
                document.getElementById('player-name').value = savedName;
                gameState.playerName = savedName;
            }

            // Guardar nombre cuando se escribe
            document.getElementById('player-name').addEventListener('input', (e) => {
                localStorage.setItem('triviaMasterName', e.target.value);
            });

            // Mostrar pantalla inicial
            showScreen('home');
        }

        // Iniciar el juego cuando se carga la página
        window.addEventListener('DOMContentLoaded', initGame);
    </script>
</body>
</html>
